function renderChanges(){const filtered=state.changesFilter==='All'?changes:changes.filter(c=>c.status===state.changesFilter);return `<div class="large-page"><div class="page-inner">${pageHead('02','ENGINEERING RECORD','Changes','A Change is an enduring record of intent, implementation, verification, and decision—not just an agent conversation.',`<button class="btn ghost" data-page="agent">Delegate to Rook</button><button class="btn primary" data-action="new-change">+ New Change</button>`)}<div class="subheading"><h2>Change register <span class="count">/ ${String(filtered.length).padStart(2,'0')}</span></h2><div class="segment">${['All','Active','In review','Integrated'].map(f=>`<button class="${state.changesFilter===f?'active':''}" data-filter-changes="${f}">${f}</button>`).join('')}</div></div><div class="table-wrap"><table class="records"><thead><tr><th>Change</th><th>State</th><th>Workspace</th><th>Diff</th><th>Updated</th><th>Open</th></tr></thead><tbody>${filtered.map(c=>`<tr data-change-id="${c.id}"><td class="record-main"><span class="record-title">${esc(c.title)}</span><span class="record-code">${c.id}</span><span class="separator-dot">·</span><span class="record-sub">${esc(c.desc)}</span></td><td>${badge(c.id==='CH-024'?(state.reviewIntegrated?'Integrated':state.reviewApproved?'Approved':'In review'):c.status)}</td><td><span class="record-sub">${esc(c.branch)}</span><div class="record-sub" style="margin-top:6px">${esc(c.owner)}</div></td><td><span class="mono green">${esc(c.diff.split('/')[0])}</span> <span class="mono red">${esc(c.diff.split('/')[1])}</span><div class="record-sub" style="margin-top:6px">${c.files}</div></td><td class="record-sub">${c.ago}</td><td class="brass mono">↗</td></tr>`).join('')}</tbody></table>${filtered.length?'':'<div class="empty-state">Nothing in this state.</div>'}</div><div class="changes-bottom"><div class="changes-note"><span class="index">01</span><div><h3>Source is always available</h3><p>Review the actual files and diffs, or return to editing at any point. A Change does not hide your code.</p></div></div><div class="changes-note"><span class="index">02</span><div><h3>Evidence belongs to a source state</h3><p>When candidate source changes, prior tests are not automatically proof for the new revision.</p></div></div></div></div></div>`}
function renderReview(){const change=changes.find(c=>c.id===(state.reviewChangeId||'CH-024'))||changes[0],sample=change.id==='CH-024',currentStatus=sample?(state.reviewIntegrated?'Integrated':state.reviewApproved?'Approved':change.status):change.status;const fileOptions=sample?Object.keys(diffSets):[];const chosen=diffSets[state.reviewFile]||diffSets['src/services/session.ts'];let diffMarkup=sample?`<div class="review-files"><span class="muted micro" style="margin-right:7px">FILES / 03</span>${fileOptions.map(file=>`<button data-review-file="${esc(file)}" class="review-file ${state.reviewFile===file?'active':''}">${esc(file.split('/').pop())}</button>`).join('')}<span class="spacer"></span><button class="btn tiny ghost" data-action="edit-review-source">Open in editor ↗</button></div><div class="diff-window"><div class="diff-head"><span class="brass">${esc(state.reviewFile)}</span><span class="muted">UNIFIED DIFF <span class="separator-dot">·</span> CANDIDATE</span></div><div class="diff-code">${chosen.map(row=>`<div class="diff-line ${row[0]}"><span class="num">${row[1]}</span><span class="num">${row[2]}</span><span class="sign">${row[0]==='add'?'+':row[0]==='del'?'−':row[0]==='hunk'?'@@':''}</span><span>${esc(row[3])}</span></div>`).join('')}</div></div>`:`<div class="quiet-panel mt24"><div class="eyebrow">SAMPLE RECORD ONLY</div><h3 style="margin-top:12px">No diff preview prepared.</h3><p>This is a separate illustrative Change. The detailed review example is CH-024, which has example source diffs and evidence.</p><button class="btn primary" data-action="focus-example-change">Open CH-024 ↗</button></div>`;return `<div class="review-layout"><section class="review-center"><button class="back-button" data-page="changes">← &nbsp; ALL CHANGES</button><div class="review-top"><div class="eyebrow">${change.id} <span class="separator-dot">/</span> CANDIDATE REVIEW</div><h1>${esc(change.title)}</h1><p class="review-desc">${esc(change.desc)} ${sample?'Review the implementation directly against its acceptance criteria, then decide whether it is ready to integrate.':''}</p><div class="review-meta">${badge(currentStatus)}<span class="micro">${esc(change.branch)}</span><span class="micro">${esc(change.diff)} lines</span><span class="micro muted">${change.files}</span></div></div><div class="subheading" style="margin-top:15px"><h2>Source changes <span class="count">/ ${sample?'03':'—'}</span></h2><span class="micro muted">BASE → CANDIDATE</span></div>${diffMarkup}${sample?`<div class="eyebrow mt24">REVIEW ANNOTATION</div><div class="review-annotation">The session row is locked during token rotation. The second concurrent request should observe that the token has already been revoked, then fail without issuing a second pair.</div><button class="text-action" data-page="context">Trace the related symbols in Context Lens ↗</button>`:''}</section><aside class="review-aside"><div class="aside-section"><div class="eyebrow">REVIEW CONTROL</div><h3 style="font:normal 27px var(--serif);margin:11px 0 7px">${sample?'Ready for scrutiny.':'Change details.'}</h3><p class="page-caption">${sample?'Candidate snapshot 8c2a9f. All verification is illustrative and tied to this sample revision.':'This mock record has no stored evidence preview.'}</p></div><div class="aside-section"><div class="subheading" style="padding-top:0"><h2>Acceptance criteria</h2><span class="count">${sample?'03 / 03':'—'}</span></div>${sample?['A refresh token is accepted only once','Concurrent attempts cannot both succeed','Session creation remains atomic'].map(x=>`<div class="criteria-row"><span class="check-circle">✓</span><span>${x}</span></div>`).join(''):'<p class="page-caption">No criteria in this sample record.</p>'}</div><div class="aside-section"><div class="subheading" style="padding-top:0"><h2>Verification</h2><button class="row-link" data-page="verify">Ledger ↗</button></div>${sample?`<div class="evidence-row"><span class="name">Unit tests <span class="dim">/ 6</span></span>${badge(state.reviewStale?'Stale':'Passed')}</div><div class="evidence-row"><span class="name">Typecheck</span>${badge(state.reviewStale?'Stale':'Passed')}</div><div class="evidence-row"><span class="name">Lint</span>${badge(state.reviewStale?'Stale':'Passed')}</div><div class="evidence-row"><span class="name">Source identity</span><span class="brass">8c2a9f</span></div><div class="micro muted mt12">Evidence describes this sample source state only.</div>`:'<p class="page-caption">No verification evidence provided.</p>'}</div><div class="aside-section"><div class="subheading" style="padding-top:0"><h2>Decision</h2><span class="count">DEVELOPER</span></div>${sample?`${state.reviewStale?'<div class="warning-note">Sample candidate was marked modified. Prior approvals and checks are stale; fresh evidence is required.</div>':''}${state.reviewApproved?'<div class="pill green mt12">✓ Approved in UI prototype</div>':''}${state.reviewIntegrated?'<div class="pill green mt12">✓ Integration state simulated</div>':''}<div class="review-actions"><button class="btn ghost" data-action="request-revision">Request revision</button><button class="btn primary" data-action="approve-review" ${state.reviewStale||state.reviewIntegrated?'disabled':''}>${state.reviewApproved?'Revoke approval':'Approve'}</button></div><button class="btn ghost mt12" style="width:100%" data-action="integrate-review" ${!state.reviewApproved||state.reviewStale||state.reviewIntegrated?'disabled':''}>Prepare integration ↗</button><div class="micro muted mt12">Buttons modify only the demo UI, never Git.</div>`:'<button class="btn ghost mt12" data-action="focus-example-change">Inspect CH-024 example ↗</button>'}</div><div class="eyebrow">SCOPE / ISOLATION</div><p class="page-caption mt12">Candidate files are represented as a separate worktree. Worktrees are not process-security sandboxes.</p></aside></div>`}
function renderContext(){const selected=nodes.find(n=>n.id===state.selectedNode)||nodes[1];return `<div class="large-page"><div class="page-inner">${pageHead('03','SYSTEM UNDERSTANDING','Context Lens','A navigable map from code relationships and engineering records. Observations stay distinguishable from inferred connections.',`<button class="btn ghost" data-page="editor">Return to source ↗</button>`)}<div class="subheading"><h2>Authentication domain <span class="count">/ ATLAS API</span></h2><span class="pill blue">LSP-GROUNDED EXAMPLE</span></div><div class="context-grid"><div class="diagram-area"><div class="diagram-top"><span class="eyebrow">SYSTEM EXPLORER / 003 NODES</span><span class="micro muted">DEPENDENCY DIRECTION →</span></div><div class="architecture">${nodes.map(n=>`<button class="architecture-node ${state.selectedNode===n.id?'selected':''}" data-node="${n.id}"><span class="node-id">${n.number}</span><strong>${esc(n.name)}</strong><small>${esc(n.detail)}</small></button>`).join('')}</div><div class="architecture-foot"><span class="diagram-legend"><span class="legend-line"></span> Source-linked relationship</span><span class="diagram-legend">CLICK A NODE TO INSPECT</span></div></div><div class="context-detail"><div class="eyebrow">SELECTED NODE <span class="separator-dot">/</span> ${selected.number}</div><h3>${esc(selected.name)}</h3><p>${esc(selected.detail)}. The map shows source-level relationships in the authentication flow rather than claiming to know the entire runtime architecture.</p><div class="detail-row"><span>Confidence</span>${badge(selected.kind)}</div><div class="detail-row"><span>Related references</span><span>${selected.refs}</span></div><div class="detail-row"><span>Primary source</span><span class="brass">${esc(selected.source.split('/').pop())}</span></div><div class="detail-row"><span>Linked record</span><button class="text-action" data-page="review">CH-024 ↗</button></div><button class="btn primary mt24" data-file="${esc(selected.source)}">Open source file ↗</button></div></div><div class="relationships"><div class="subheading"><h2>Source relationships <span class="count">/ 03</span></h2><span class="micro muted">EVIDENCE LABELS ARE EXPLICIT</span></div>${[['POST /auth/refresh','src/routes/auth.ts','Calls rotateSession','Observed'],['rotateSession','src/services/session.ts','Issues a token pair','Observed'],['validateRefreshToken','src/lib/token.ts','Protects session route','Inferred']].map(x=>`<button class="relation-row" data-file="${x[1]}"><div><div class="rel-name">${esc(x[0])}</div><div class="rel-sub">${esc(x[1])}</div></div><div class="tag">${esc(x[2])}</div><div style="text-align:right">${badge(x[3])}</div></button>`).join('')}</div><div class="system-timeline"><div class="changes-note"><span class="index">01</span><div><h3>History carries intent</h3><p>Change records attach past decisions and test evidence to navigable source, rather than summarizing code without provenance.</p></div></div><div class="changes-note"><span class="index">02</span><div><h3>Inference is not fact</h3><p>Developer-confirmed and source-observed links remain separate from suggested relationships that require review.</p></div></div></div></div></div>`}
function renderVerify(){const entries=[{name:'Refresh token reuse',cmd:'vitest · auth.test.ts',when:'2m 13s',type:state.reviewStale?'Stale':'Passed',icon:'✓'},{name:'Concurrent refresh attempts',cmd:'vitest · auth.test.ts',when:'2m 11s',type:state.reviewStale?'Stale':'Passed',icon:'✓'},{name:'TypeScript project check',cmd:'tsc --noEmit',when:'2m 08s',type:state.reviewStale?'Stale':'Passed',icon:'✓'},{name:'Static lint check',cmd:'eslint src/',when:'2m 06s',type:state.reviewStale?'Stale':'Passed',icon:'✓'},{name:'API integration suite',cmd:'pnpm test:integration',when:'Not run',type:'Not run',icon:'–'}];const filtered=state.verifyFilter==='All'?entries:entries.filter(e=>e.type===state.verifyFilter);return `<div class="large-page"><div class="page-inner">${pageHead('04','VERIFICATION RECORD','Evidence, not assertion.','Executions, source identities, and observed results belong together. A passing check is evidence for a specific saved source state.',`<button class="btn ghost" data-page="review">Return to review ↗</button><button class="btn primary" data-action="sample-rerun">Request new verification</button>`)}<div class="verify-summary"><div><div class="eyebrow">CANDIDATE / CH-024</div><div class="big-status ${state.reviewStale?'red':'green'}">${state.reviewStale?'Stale':'Passed'}</div><small>${state.reviewStale?'Candidate edited after evidence capture':'4 sample checks passed · 1 not run'}</small></div><div><div class="eyebrow">TESTED SOURCE</div><div class="big-status">8c2a9f</div><small>Immutable sample snapshot ID</small></div><div><div class="eyebrow">RECORDED EXECUTION</div><div class="big-status">04</div><small>Sample records with associated source state</small></div></div><div class="subheading"><h2>Verification ledger <span class="count">/ ${String(filtered.length).padStart(2,'0')}</span></h2><div class="segment">${['All','Passed','Stale','Not run'].map(f=>`<button class="${state.verifyFilter===f?'active':''}" data-verify-filter="${f}">${f}</button>`).join('')}</div></div><div class="verify-ledger"><div>${filtered.map((e,i)=>`<div class="ledger-row"><span class="ledger-icon ${e.type==='Stale'?'stale':''}">${e.icon}</span><span><div class="ledger-title">${esc(e.name)}</div><div class="ledger-sub">${esc(e.cmd)}</div></span><span>${badge(e.type)}</span><span class="ledger-time">${e.when}</span></div>`).join('')}${filtered.length?'':'<div class="empty-state">No records in this category.</div>'}<div class="changes-note" style="margin-top:30px"><span class="index">!</span><div><h3>What the result does not claim</h3><p>These sample checks are not proof that the whole application is correct. Unrun checks and unobserved behavior remain explicitly unknown.</p></div></div></div><aside class="evidence-sheet"><div class="eyebrow">SOURCE MANIFEST / EXAMPLE</div><h3>A precise record.</h3><p>Each check should bind to a content-addressed source manifest and relevant environment details, rather than relying on a Git HEAD label alone.</p><div class="snapshot"><div>candidate <span class="hash">8c2a9f</span></div><div>branch <strong>laplace/ch-024</strong></div><div>source <strong>tracked + relevant untracked</strong></div><div>lockfile <strong>pnpm-lock.yaml</strong></div><div>runtime <strong>Node.js / illustrative</strong></div><div>result <span class="${state.reviewStale?'red':'ok'}">${state.reviewStale?'stale':'passed'}</span></div></div><button class="btn ghost mt18" data-page="review">View related Change ↗</button><p class="micro muted mt18">Illustrative evidence only. This static HTML cannot run or validate code.</p></aside></div></div>`}
function renderAgent(){const sessions=[['CH-024','Session rotation review','Awaiting developer'],['CH-023','Investigate request traces','Planning'],['ASK-018','Explain token validation','Complete']];const policy=state.agentMode==='Plan'?'Read-only exploration. File inspection, searches, and safe Git reads are allowed; writes and side-effecting commands are not.':'Implementation may modify approved candidate files. Mutating commands require scope authorization and applicable tool permissions.';return `<div class="agent-layout"><aside class="agent-sessions"><div class="panel-header"><span class="panel-title">ROOK SESSIONS</span><span class="count">03</span></div><div style="padding:14px 15px"><button class="btn ghost" style="width:100%" data-action="new-agent-session">+ New session</button></div>${sessions.map((s,i)=>`<button class="session-row ${state.agentSession===i?'active':''}" data-agent-session="${i}"><span class="session-index">${String(i+1).padStart(2,'0')}</span><span><strong>${s[1]}</strong><small>${s[0]} · ${s[2]}</small></span></button>`).join('')}<div class="quiet-panel" style="margin:18px 14px;background:transparent;padding:14px"><div class="eyebrow">HARNESS / BOUNDARY</div><p class="small mt12">Laplace manages Changes and evidence. Rook retains control over agent execution and permissions.</p></div></aside><section class="agent-center"><div class="agent-heading"><div class="eyebrow">05 / CONTEXTUAL DELEGATION</div><h1>Rook workspace.</h1><p>Investigate with context, propose a patch, or delegate a substantial Change without losing your source.</p></div><div class="agent-stream"><div class="agent-event"><span class="time">09:41</span><div class="event-body"><span class="event-label">YOU / CHANGE INTENT</span><h3>Review the refresh-token rotation path.</h3><p>Inspect how concurrent requests are handled and propose a safe way to ensure that only one refresh succeeds.</p></div></div><div class="agent-event"><span class="time">09:42</span><div class="event-body"><span class="event-label">ROOK / INVESTIGATION <span class="pill blue" style="margin-left:8px">SAMPLE EVENT</span></span><h3>Source relationships identified.</h3><p>The route calls <span class="mono brass">rotateSession</span>, which revokes the existing token and creates a new pair. An exclusive lock prevents simultaneous consumption.</p><div class="event-code">read &nbsp; src/routes/auth.ts<br>read &nbsp; src/services/session.ts<br>search &nbsp; "rotateSession"</div></div></div><div class="agent-event"><span class="time">09:43</span><div class="event-body"><span class="event-label">ROOK / RECOMMENDATION</span><h3>Proceed as an isolated Change.</h3><p>Introduce row-level locking and a concurrency regression test in a candidate workspace, then compare the verified source before integration.</p><button class="text-action mt12" data-page="review">Open the candidate Change ↗</button></div></div>${state.agentPrompts.map(p=>`<div class="agent-event"><span class="time">NOW</span><div class="event-body"><span class="event-label">YOU / MOCK PROMPT</span><h3>${esc(p)}</h3><p>This was added to the local interface only. No request was sent to Rook.</p></div></div>`).join('')}</div><div class="agent-composer"><div class="agent-compose-input"><textarea id="agent-prompt" rows="2" placeholder="Ask, inspect, patch, or describe a Change…"></textarea><button class="btn primary" data-action="send-agent">Send ↗</button></div><div class="agent-composer-bottom"><span>⊕ &nbsp; src/routes/auth.ts</span><span>◷ &nbsp; Source-aware context</span><span class="spacer"></span><span class="brass">${state.agentMode.toUpperCase()} MODE</span></div></div></section><aside class="agent-aside"><div class="eyebrow">AGENT CONTROLS</div><h3 class="insight-title" style="margin:13px 0 16px">Explicit authority.</h3><div class="panel-title">EXECUTION MODE</div><div class="mode-selector"><button class="${state.agentMode==='Plan'?'active':''}" data-agent-mode="Plan">◇ &nbsp; Plan</button><button class="${state.agentMode==='Build'?'active':''}" data-agent-mode="Build">◆ &nbsp; Build</button></div><div class="agent-policy">${policy}</div><div class="subheading mt24"><h2>Attached context</h2><span class="count">02</span></div><div class="agent-context-item"><span>auth.ts <span class="muted">/ 18–34</span></span><span class="brass">×</span></div><div class="agent-context-item"><span>CH-024 <span class="muted">/ criteria</span></span><span class="brass">×</span></div><div class="permission-box"><div class="eyebrow">PERMISSION / EXAMPLE</div><h3>${state.agentMode==='Plan'?'Filesystem write blocked':'Candidate write proposed'}</h3><p>${state.agentMode==='Plan'?'A planned write cannot proceed in Plan mode; choose Build and review the requested operation.':'An agent requests access to modify the candidate workspace. Source ownership and permissions stay explicit.'}</p><div class="page-actions" style="margin-top:14px">${state.agentMode==='Plan'?'<button class="btn tiny ghost" data-agent-mode="Build">Switch to Build</button>':'<button class="btn tiny ghost" data-action="deny-permission">Deny</button><button class="btn tiny primary" data-action="approve-permission">Approve in demo</button>'}</div></div><p class="micro muted mt18">All sessions and permission prompts shown are illustrative.</p></aside></div>`}
function renderCapabilities(){const isSkills=state.capTab==='Skills',items=isSkills?skills:mcps,selected=items.find(c=>c.id===state.capSelected)||items[0];return `<div class="large-page"><div class="page-inner">${pageHead('06','AGENT CAPABILITIES','Tools & capabilities.','Inspect what Rook can access, where each capability comes from, and what authority it carries. Enabled tools are never a substitute for permission.',`<button class="btn ghost" data-page="agent">Open Rook workspace ↗</button><button class="btn primary" data-action="add-capability">+ Add capability</button>`)}<div class="subheading"><div class="segment"><button class="${isSkills?'active':''}" data-cap-tab="Skills">Skills <span class="dim">04</span></button><button class="${!isSkills?'active':''}" data-cap-tab="MCP">MCP servers <span class="dim">03</span></button></div><span class="micro muted">ILLUSTRATIVE CONFIGURATION / MANAGED BY ROOK</span></div><div class="cap-grid"><section>${items.map(c=>`<div class="cap-row"><div class="cap-leading"><button class="cap-symbol" data-cap-selected="${c.id}">${c.glyph}</button><div><button class="cap-name" data-cap-selected="${c.id}" style="text-align:left">${esc(c.name)} <span class="dim mono" style="font-size:10px">↗</span></button><div class="cap-sub">${esc(c.description)}</div><div class="cap-sub" style="margin-top:6px">${esc(c.origin)} <span class="separator-dot">/</span> ${esc(c.scope)}</div></div></div><div class="cap-controls">${!isSkills?badge(c.enabled?'Connected':'Disabled'):''}<button class="toggle ${c.enabled?'on':''}" type="button" role="switch" aria-checked="${c.enabled?'true':'false'}" aria-label="Toggle ${esc(c.name)}" data-toggle-cap="${c.id}"></button></div></div>`).join('')}<p class="micro muted mt18">Switches are local UI controls. No actual Rook or MCP configuration is modified.</p></section><aside class="cap-detail"><div class="eyebrow">${isSkills?'SKILL':'MCP SERVER'} DETAILS</div><h3>${esc(selected.name)}</h3><p>${esc(selected.description)}</p><div class="meta-table"><div class="meta-row"><span>Origin</span><span>${esc(selected.origin)}</span></div><div class="meta-row"><span>Authority</span><span>${esc(selected.scope)}</span></div><div class="meta-row"><span>State</span>${badge(selected.enabled?'Enabled':'Disabled')}</div><div class="meta-row"><span>Identifier</span><span class="brass">${esc(selected.id)}</span></div></div><div class="eyebrow mt24">VISIBLE ${isSkills?'TOOLS':'METHODS'}</div><div class="snapshot">${esc(selected.tools).replaceAll(' · ','<br>')}</div><div class="insight-callout"><span class="eyebrow">TRUST BOUNDARY</span><p style="margin:7px 0 0">Capability definitions and external responses are untrusted input. Execution must still respect the effective approval policy.</p></div><button class="btn ghost mt18" data-action="inspect-capability">View configuration ↗</button></aside></div></div></div>`}
function renderSettings(){return `<div class="large-page"><div class="page-inner">${pageHead('07','PREFERENCES','A quieter environment.','Every surface is considered for clarity, keyboard access, and long hours of uninterrupted work. Settings here affect only this HTML prototype.')}
 <div class="settings-layout"><nav class="settings-menu" aria-label="Settings sections">${['Appearance','Editor','Workflows','Privacy'].map(x=>`<button class="${state.settingsSection===x?'active':''}" data-settings-section="${x}">${x}</button>`).join('')}</nav><section>${state.settingsSection==='Appearance'?`<div class="settings-group"><h2>Appearance</h2><p>A restrained system designed for long-form reading, source inspection, and careful review.</p><div class="setting-row"><div><strong>Color treatment</strong><small>Graphite / brass, or a matching daylight palette.</small></div><div class="segment"><button class="${state.theme==='dark'?'active':''}" data-theme="dark">Dark</button><button class="${state.theme==='light'?'active':''}" data-theme="light">Light</button></div></div><div class="setting-row"><div><strong>Interface density</strong><small>Prefer information over decorative whitespace.</small></div><select id="density-select"><option ${state.density==='Comfortable'?'selected':''}>Comfortable</option><option ${state.density==='Compact'?'selected':''}>Compact</option></select></div><div class="setting-row"><div><strong>Source font size</strong><small>Monospaced text in the editor view.</small></div><select id="font-select"><option value="11" ${state.fontSize===11?'selected':''}>11 px</option><option value="12" ${state.fontSize===12?'selected':''}>12 px</option><option value="13" ${state.fontSize===13?'selected':''}>13 px</option><option value="14" ${state.fontSize===14?'selected':''}>14 px</option></select></div></div><div class="preference-preview"><div class="eyebrow">LIVE COLOR PREVIEW</div><h3 style="font:normal 25px var(--serif);margin:15px 0 4px">Quietly capable.</h3><p><span class="brass">export</span> <span class="strong">const</span> workspace = <span class="green">"thoughtful"</span>;</p></div>`:state.settingsSection==='Editor'?`<div class="settings-group"><h2>Editor</h2><p>The source editor is always available directly; code is never hidden behind agent interactions.</p><div class="setting-row"><div><strong>Source editing</strong><small>In the prototype, switch to Edit file and change the sample text.</small></div><button class="btn ghost" data-page="editor">Open editor ↗</button></div><div class="setting-row"><div><strong>Split editors</strong><small>Planned capability for the production workspace.</small></div><span class="pill">PLANNED</span></div><div class="setting-row"><div><strong>Vim keybindings</strong><small>Optional in the implementation plan.</small></div><span class="pill">DEFERRED</span></div></div>`:state.settingsSection==='Workflows'?`<div class="settings-group"><h2>Workflows</h2><p>Explicit control over execution, handoff, review, and integration.</p><div class="setting-row"><div><strong>Verification freshness</strong><small>Invalidate existing evidence when relevant source changes.</small></div><span class="pill green">REQUIRED POLICY</span></div><div class="setting-row"><div><strong>Agent plan mode</strong><small>Read-only investigation enforced by tool permissions.</small></div><span class="pill green">READ-ONLY</span></div><div class="setting-row"><div><strong>Integration</strong><small>Review and approve the proposed destination state.</small></div><span class="pill gold">EXPLICIT</span></div></div>`:`<div class="settings-group"><h2>Local trust and privacy</h2><p>The intended product operates on local repositories. This demonstration does not access any actual filesystem beyond these static assets.</p><div class="setting-row"><div><strong>Network access</strong><small>No requests from the mockup.</small></div><span class="pill green">OFFLINE</span></div><div class="setting-row"><div><strong>Project data</strong><small>Hardcoded sample records only.</small></div><span class="pill neutral">ILLUSTRATIVE</span></div><div class="setting-row"><div><strong>Integration permissions</strong><small>No Git operations in this prototype.</small></div><span class="pill green">NO BACKEND</span></div></div>`}<div class="changes-note mt24"><span class="index">⌘</span><div><h3>Designed around the keyboard</h3><p>Use ⌘K or Ctrl+K to switch screens or open sample files. Ctrl/⌘ + 1–7 moves between major views.</p></div></div></section></div></div></div>`}
function handleAction(action,el){
 if(action==='toggle-terminal'){state.terminal=!state.terminal;render();return}
 if(action==='edit-editor'){state.editorMode='edit';render();$('#source-editor')?.focus();return}
 if(action==='view-editor'){state.editorMode='view';render();return}
 if(action==='save-editor'){files[state.file].dirty=false;toast(state.editingCandidate?'Sample candidate saved in page memory. Earlier evidence is now marked stale.':'Sample edit saved in page memory only; no disk file was changed.');render();return}
 if(action==='insight-context'||action==='insight-history'){state.insightTab=action==='insight-context'?'context':'history';render();return}
 if(['insight-ask','insight-patch','insight-change'].includes(action)){state.agentMode=action==='insight-change'?'Build':'Plan';goto('agent');toast(`${action.split('-')[1].toUpperCase()} handoff preview. No agent started.`);return}
 if(action==='send-context'){let prompt=$('#context-prompt')?.value.trim();if(prompt)state.agentPrompts.push(prompt);goto('agent');toast('Context transferred to the Rook demo panel. No external request was sent.');return}
 if(action==='new-change'){state.agentMode='Build';goto('agent');toast('A production New Change composer would collect goals and criteria. Demo only.');return}
 if(action==='edit-review-source'){const f=state.reviewFile;openFile(f);state.editingCandidate=true;state.editorMode='edit';render();toast('Editing the illustrative candidate workspace. New edits invalidate earlier sample evidence.');return}
 if(action==='approve-review'){state.reviewApproved=!state.reviewApproved;toast(state.reviewApproved?'Approved in the UI concept only; no persistent record was created.':'Approval revoked in the UI concept.');render();return}
 if(action==='request-revision'){state.reviewApproved=false;toast('Revision requested in prototype only. No Rook command or repository write occurred.');render();return}
 if(action==='integrate-review'){state.reviewIntegrated=true;toast('Integration state illustrated. No Git merge or commit was performed.');render();return}
 if(action==='focus-example-change'){state.reviewChangeId='CH-024';goto('review');return}
 if(action==='sample-rerun'){toast('A real Laplace would run an approved check against a new source manifest. No check was executed here.');return}
 if(action==='new-agent-session'){state.agentSession=0;state.agentPrompts=[];render();toast('New session shown in prototype. No Rook session was created.');return}
 if(action==='send-agent'){const value=$('#agent-prompt')?.value.trim();if(!value){toast('Enter an example request to add it to this local mock conversation.');return}state.agentPrompts.push(value);render();toast('Prompt shown locally. No model call or Rook execution occurred.');return}
 if(action==='approve-permission'||action==='deny-permission'){toast(action==='approve-permission'?'Permission approved visually only; no operation was authorized.':'Permission denied visually only.');return}
 if(action==='add-capability'||action==='inspect-capability'){toast('Configuration editor is not connected in this static demonstration.');return}
}
function installHandlers(){
 document.addEventListener('click',event=>{
  const target=event.target.closest('button,[data-change-id],tr[data-change-id]');if(!target)return;
  if(target.id==='open-command'){openPalette();return}
  if(target.dataset.page){goto(target.dataset.page);return}
  if(target.dataset.file){openFile(target.dataset.file);return}
  if(target.dataset.changeId){state.reviewChangeId=target.dataset.changeId;goto('review');return}
  if(target.dataset.filterChanges){state.changesFilter=target.dataset.filterChanges;render();return}
  if(target.dataset.reviewFile){state.reviewFile=target.dataset.reviewFile;render();return}
  if(target.dataset.verifyFilter){state.verifyFilter=target.dataset.verifyFilter;render();return}
  if(target.dataset.node){state.selectedNode=target.dataset.node;render();return}
  if(target.dataset.agentSession!==undefined){state.agentSession=Number(target.dataset.agentSession);render();return}
  if(target.dataset.agentMode){state.agentMode=target.dataset.agentMode;render();return}
  if(target.dataset.capTab){state.capTab=target.dataset.capTab;state.capSelected=(state.capTab==='Skills'?skills:mcps)[0].id;render();return}
  if(target.dataset.capSelected){state.capSelected=target.dataset.capSelected;render();return}
  if(target.dataset.toggleCap){const group=state.capTab==='Skills'?skills:mcps,entry=group.find(c=>c.id===target.dataset.toggleCap);if(entry){entry.enabled=!entry.enabled;toast(`${entry.name} ${entry.enabled?'enabled':'disabled'} in this page only.`);render()}return}
  if(target.dataset.settingsSection){state.settingsSection=target.dataset.settingsSection;render();return}
  if(target.dataset.theme){state.theme=target.dataset.theme;document.body.classList.toggle('light',state.theme==='light');render();return}
  if(target.dataset.action){handleAction(target.dataset.action,target);return}
  if(target.dataset.toast){toast(target.dataset.toast);return}
 });
 document.addEventListener('input',e=>{if(e.target.id==='source-editor'){files[state.file].content=e.target.value;files[state.file].dirty=true;if(state.editingCandidate){state.reviewStale=true;state.reviewApproved=false}const crumb=$('.editor-context-bar .pill');if(crumb){crumb.textContent='UNSAVED';crumb.className='pill gold'}}});
 document.addEventListener('change',e=>{if(e.target.id==='font-select'){state.fontSize=Number(e.target.value);document.documentElement.style.setProperty('--code-size',`${state.fontSize}px`);render()}if(e.target.id==='density-select'){state.density=e.target.value;document.body.classList.toggle('compact',state.density==='Compact');toast(`Interface density set to ${state.density.toLowerCase()} in this prototype.`)}});
 document.addEventListener('keydown',e=>{
  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.paletteOpen?closePalette():openPalette();return}
  if(state.paletteOpen){if(e.key==='Escape'){e.preventDefault();closePalette()}else if(e.key==='ArrowDown'){e.preventDefault();state.paletteIndex=Math.min(state.paletteIndex+1,state.paletteItems.length-1);renderPaletteList()}else if(e.key==='ArrowUp'){e.preventDefault();state.paletteIndex=Math.max(0,state.paletteIndex-1);renderPaletteList()}else if(e.key==='Enter'){e.preventDefault();const item=state.paletteItems[state.paletteIndex];if(item){closePalette();item.run()}}return}
  if((e.metaKey||e.ctrlKey)&&/^[1-7]$/.test(e.key)){e.preventDefault();const pages=['editor','changes','context','verify','agent','capabilities','overview'];goto(pages[Number(e.key)-1])}
 });
 $('#palette-backdrop').addEventListener('click',e=>{if(e.target.id==='palette-backdrop')closePalette()});
 $('#palette-input').addEventListener('input',()=>{state.paletteIndex=0;renderPaletteList()});
 $('#palette-results').addEventListener('click',e=>{const b=e.target.closest('[data-palette-index]');if(!b)return;const item=state.paletteItems[Number(b.dataset.paletteIndex)];if(item){closePalette();item.run()}});
}
const commands=[
 ['Open workspace','Editor · source-first editing',()=>goto('editor')],
 ['Open Changes','Change register and review',()=>goto('changes')],
 ['Review CH-024','Candidate diff and evidence',()=>{state.reviewChangeId='CH-024';goto('review')}],
 ['Open Context Lens','Source relationships',()=>goto('context')],
 ['Open verification ledger','Source-bound evidence',()=>goto('verify')],
 ['Open Rook workspace','Plan and Build delegation',()=>goto('agent')],
 ['Manage Skills and MCP','Capability permissions',()=>goto('capabilities')],
 ['Open preferences','Theme and editor settings',()=>goto('settings')],
 ['Project overview','Working state',()=>goto('overview')],
 ...Object.keys(files).map(f=>[`Open ${f}`,`Source file · ${f.split('/').pop()}`,()=>openFile(f)])
];
function renderPaletteList(){const q=$('#palette-input').value.trim().toLowerCase();state.paletteItems=commands.filter(x=>`${x[0]} ${x[1]}`.toLowerCase().includes(q)).map(x=>({title:x[0],desc:x[1],run:x[2]}));state.paletteIndex=Math.min(state.paletteIndex,Math.max(0,state.paletteItems.length-1));$('#palette-results').innerHTML=state.paletteItems.length?state.paletteItems.map((c,i)=>`<button class="palette-item ${i===state.paletteIndex?'active':''}" data-palette-index="${i}"><svg viewBox="0 0 24 24"><path d="M4 12h16m-6-6 6 6-6 6"/></svg><span class="label">${esc(c.title)}</span><span class="desc">${esc(c.desc)}</span></button>`).join(''):'<p class="muted" style="padding:15px">No matching commands.</p>'}
function openPalette(){state.paletteOpen=true;$('#palette-backdrop').hidden=false;$('#palette-input').value='';renderPaletteList();$('#palette-input').focus()}
function closePalette(){state.paletteOpen=false;$('#palette-backdrop').hidden=true}
installHandlers();render();
